/** Collectible system for overlap-based pickups (coins, gems, powerups, etc.). */

import type { BabylonHandles } from "../adapters/babylonScene.ts";
import type { Possession } from "../framework/mode.ts";
import type { Resources } from "../kernel/resources.ts";
import type { SignalBus } from "../kernel/signals.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { EntityId, World } from "../kernel/world.ts";

export type CollectibleComp = {
  kind: "coin" | "gem" | "health" | "powerup" | "key" | "custom";
  value?: number;
  onCollect?: string;
  respawn?: number;
};

type CollectibleState = {
  collected: boolean;
  respawnTimer: number;
  originalY: number;
};

const collectibleStates = new Map<EntityId, CollectibleState>();

export function createCollectibleSystem(
  world: World,
  handles: BabylonHandles,
  resources: Resources,
  signals: SignalBus,
  possession: Possession,
): GameSystem {
  return {
    name: "collectible",
    order: 30,
    init() {
      for (const [id] of world.query("collectible")) {
        const pos = world.worldPosition(id);
        collectibleStates.set(id, {
          collected: false,
          respawnTimer: 0,
          originalY: pos.y,
        });
      }
    },
    fixedUpdate(ctx) {
      const pawnId = possession.pawnId;
      if (pawnId == null) return;

      const pawnPos = world.worldPosition(pawnId);
      const pawnCollider = world.getComponent<{ size: number }>("collider", pawnId);
      const pawnRadius = (pawnCollider?.size ?? 1) * 0.5;

      for (const [id, raw] of world.query("collectible")) {
        const collectible = raw as CollectibleComp;
        const state = collectibleStates.get(id);
        if (!state) continue;

        // Handle respawn timer
        if (state.collected) {
          if (collectible.respawn != null && collectible.respawn > 0) {
            state.respawnTimer -= ctx.fixedDt;
            if (state.respawnTimer <= 0) {
              state.collected = false;
              const node = handles.nodes.get(id);
              if (node) node.setEnabled(true);
            }
          }
          continue;
        }

        // Check overlap with pawn
        const pos = world.worldPosition(id);
        const collider = world.getComponent<{ size: number }>("collider", id);
        const radius = (collider?.size ?? 0.5) * 0.5;

        const dx = pawnPos.x - pos.x;
        const dy = pawnPos.y - pos.y;
        const dz = pawnPos.z - pos.z;
        const distSq = dx * dx + dy * dy + dz * dz;
        const touchDist = pawnRadius + radius;

        if (distSq < touchDist * touchDist) {
          // Collected!
          state.collected = true;
          state.respawnTimer = collectible.respawn ?? 0;

          // Hide the collectible
          const node = handles.nodes.get(id);
          if (node) node.setEnabled(false);

          // Apply effect based on kind
          applyCollectibleEffect(world, pawnId, collectible, possession);

          // Fire signal
          if (collectible.onCollect) {
            signals.emit(collectible.onCollect, {
              collectibleId: id,
              kind: collectible.kind,
              value: collectible.value ?? 1,
            });
          }

          // Default signal
          signals.emit("collected", {
            collectibleId: id,
            kind: collectible.kind,
            value: collectible.value ?? 1,
          });
        }
      }
    },
    update(ctx) {
      // Animate collectibles (bob up and down, rotate)
      for (const [id, raw] of world.query("collectible")) {
        const state = collectibleStates.get(id);
        if (!state || state.collected) continue;

        const node = handles.nodes.get(id);
        if (node) {
          // Bob animation
          const bobOffset = Math.sin(ctx.time * 3) * 0.1;
          node.position.y = state.originalY + bobOffset;

          // Rotate
          node.rotation.y += ctx.dt * 2;
        }
      }
    },
  };
}

function applyCollectibleEffect(
  world: World,
  pawnId: EntityId,
  collectible: CollectibleComp,
  possession: Possession,
): void {
  const value = collectible.value ?? 1;

  switch (collectible.kind) {
    case "coin":
    case "gem":
      // Add to score
      possession.score += value;
      break;

    case "health": {
      // Restore health
      const attrs = world.getComponent<Array<{ name: string; value: number; max: number | null }>>(
        "attributes",
        pawnId,
      );
      if (attrs) {
        const health = attrs.find((a) => a.name === "health");
        if (health) {
          health.value = Math.min(health.value + value, health.max ?? 100);
          world.addComponent("attributes", pawnId, attrs);
        }
      }
      break;
    }

    case "powerup":
      // Powerup effects are game-specific, handled via signals
      break;

    case "key":
      // Key collection is game-specific, handled via signals
      break;

    case "custom":
      // Custom effects handled via signals
      break;
  }
}
